static bool PeExecutable(const std::wstring& path,WORD* returnedSubsystem=nullptr){HANDLE file=CreateFileW(path.c_str(),GENERIC_READ,FILE_SHARE_READ|FILE_SHARE_DELETE,nullptr,OPEN_EXISTING,FILE_ATTRIBUTE_NORMAL,nullptr);if(file==INVALID_HANDLE_VALUE)return false;IMAGE_DOS_HEADER dos{};IMAGE_FILE_HEADER header{};DWORD got=0,signature=0;WORD magic=0,subsystem=0;LARGE_INTEGER at{};bool ok=ReadFile(file,&dos,sizeof(dos),&got,nullptr)&&got==sizeof(dos)&&dos.e_magic==IMAGE_DOS_SIGNATURE&&dos.e_lfanew>0;if(ok){at.QuadPart=dos.e_lfanew;ok=SetFilePointerEx(file,at,nullptr,FILE_BEGIN)&&ReadFile(file,&signature,sizeof(signature),&got,nullptr)&&got==sizeof(signature)&&signature==IMAGE_NT_SIGNATURE&&ReadFile(file,&header,sizeof(header),&got,nullptr)&&got==sizeof(header)&&ReadFile(file,&magic,sizeof(magic),&got,nullptr)&&got==sizeof(magic);}if(ok){DWORD offset=magic==IMAGE_NT_OPTIONAL_HDR32_MAGIC?FIELD_OFFSET(IMAGE_OPTIONAL_HEADER32,Subsystem):magic==IMAGE_NT_OPTIONAL_HDR64_MAGIC?FIELD_OFFSET(IMAGE_OPTIONAL_HEADER64,Subsystem):0;ok=offset&&header.SizeOfOptionalHeader>=offset+sizeof(subsystem);if(ok){at.QuadPart=(LONGLONG)dos.e_lfanew+sizeof(signature)+sizeof(header)+offset;ok=SetFilePointerEx(file,at,nullptr,FILE_BEGIN)&&ReadFile(file,&subsystem,sizeof(subsystem),&got,nullptr)&&got==sizeof(subsystem)&&(subsystem==IMAGE_SUBSYSTEM_WINDOWS_GUI||subsystem==IMAGE_SUBSYSTEM_WINDOWS_CUI);}}CloseHandle(file);if(ok&&returnedSubsystem)*returnedSubsystem=subsystem;return ok;}
struct ZipApplications {unsigned total=0,root=0,gui=0,visited=0;bool complete=true;std::wstring totalPath,rootPath,guiPath;};
static void FindZipApplications(const std::wstring& directory,unsigned depth,ZipApplications& found){if(!found.complete||depth>32||found.visited>10000){found.complete=false;return;}WIN32_FIND_DATAW data{};HANDLE search=FindFirstFileW((directory+L"\\*").c_str(),&data);if(search==INVALID_HANDLE_VALUE)return;do{if(!wcscmp(data.cFileName,L".")||!wcscmp(data.cFileName,L".."))continue;if(++found.visited>10000){found.complete=false;break;}std::wstring path=directory+L"\\"+data.cFileName;if(data.dwFileAttributes&FILE_ATTRIBUTE_REPARSE_POINT){found.complete=false;break;}if(data.dwFileAttributes&FILE_ATTRIBUTE_DIRECTORY)FindZipApplications(path,depth+1,found);else if(EndsInsensitive(data.cFileName,L".exe")){WORD subsystem=0;if(!PeExecutable(path,&subsystem))continue;++found.total;found.totalPath=path;if(!depth){++found.root;found.rootPath=path;}if(subsystem==IMAGE_SUBSYSTEM_WINDOWS_GUI){++found.gui;found.guiPath=path;}}}while(found.complete&&FindNextFileW(search,&data));FindClose(search);}
