static bool SafeArchiveEntry(std::wstring value){for(wchar_t& c:value)if(c==L'\\')c=L'/';if(value.empty()||value[0]==L'/'||value.find(L':')!=std::wstring::npos)return false;size_t at=0;while(at<=value.size()){size_t slash=value.find(L'/',at);std::wstring part=value.substr(at,slash==std::wstring::npos?slash:slash-at);if(part==L"..")return false;if(slash==std::wstring::npos)break;at=slash+1;}return true;}
