static bool ValidateRelease(const std::wstring& path,std::wstring& kind,std::wstring& error){WIN32_FILE_ATTRIBUTE_DATA data{};if(!GetFileAttributesExW(path.c_str(),GetFileExInfoStandard,&data)){error=L"Release was not found.";return false;}if(data.dwFileAttributes&FILE_ATTRIBUTE_REPARSE_POINT){error=L"Release folders cannot contain links or reparse points.";return false;}if(data.dwFileAttributes&FILE_ATTRIBUTE_DIRECTORY){ZipApplications found;FindZipApplications(path,0,found);if(!found.complete){error=L"The release folder is too deep, contains too many files, or contains a link or reparse point.";return false;}if(!(found.total==1||found.root==1||found.gui==1)){error=L"The release folder does not contain an unambiguous application executable.";return false;}kind=L"folder";return true;}unsigned long long size=((unsigned long long)data.nFileSizeHigh<<32)|data.nFileSizeLow;if(!size||size>MaxReleaseBytes){error=L"Release files must be between 1 byte and 100 MiB.";return false;}if(EndsInsensitive(path,L".exe")){if(!PeExecutable(path)){error=L"The release executable is invalid.";return false;}kind=L"exe";return true;}if(EndsInsensitive(path,L".zip")){if(!ValidateZip(path,error))return false;kind=L"zip";return true;}error=L"Release must be an executable, ZIP, or folder.";return false;}
