static bool SaveAndBuildSettings(Project& project,const Project& requested,const std::wstring& projects,std::wstring& output,std::wstring& error){std::wstring kind;if(!ValidateRelease(requested.release,kind,error))return false;for(const auto& other:LoadProjects(projects))if(other.appId!=project.appId&&!_wcsicmp(other.name.c_str(),requested.name.c_str())){error=L"App names must be unique.";return false;}Project edited=requested;edited.directory=project.directory;std::wstring oldLauncher=LauncherPath(project),newLauncher=LauncherPath(edited);bool launcherRenamed=_wcsicmp(oldLauncher.c_str(),newLauncher.c_str())!=0,copied=false;if(launcherRenamed&&Exists(oldLauncher)){if(!CopyFileW(oldLauncher.c_str(),newLauncher.c_str(),FALSE)){error=L"Could not prepare the renamed launcher.";return false;}copied=true;}if(!BuildLauncher(edited,error,&output)){if(copied)DeleteFileW(newLauncher.c_str());return false;}if(!SaveProject(projects,edited,error)){if(copied)DeleteFileW(newLauncher.c_str());return false;}if(launcherRenamed){std::wstring stale=edited.directory+L"\\"+project.name+L".exe";if(Exists(stale))DeleteFileW(stale.c_str());}project=edited;return true;}
static bool EditSettings(Project& project,const std::wstring& projects,size_t selected=0,bool activate=false){
    Project edited=project;
    for(;;){
        std::vector<ProjectSettingRow> rows=ProjectSettingRows(edited);
        size_t actionStart=rows.size();if(!edited.repo.empty())rows.push_back({L"Push Settings",L""});rows.push_back({L"Save & Rebuild",L""});
        if(selected>=rows.size())selected=0;
        std::wstring alert=!SameSettings(project,edited)?L"unsaved changes":(Dirty(edited)?L"settings need pushing":L"");Header(project.name,L"· Settings",alert);
        for(size_t i=0;i<rows.size();++i){if(i==actionStart)Out(L"\n");SettingMenuRow(rows[i].label,rows[i].value,rows[i].nonDefault,i,selected);}Help(false,L"Discard Changes");
        std::wstring choice;if(activate){choice=L"select";activate=false;}else if(!MenuInput(choice,L"",&selected))return false;choice=Lower(choice);
        if(choice==L"redraw")continue;
        if(choice==L"q"){if(SameSettings(project,edited))return false;bool discard=false;if(YesNo(L"Discard unsaved changes",false,discard)&&discard)return false;continue;}
        if(MoveSelection(choice,rows.size(),selected))continue;
        size_t action=0;if(!ChosenAction(choice,rows.size(),selected,action))continue;
        const std::wstring label=rows[action].label;std::wstring error;
        if(action<actionStart){EditProjectSetting(edited,label,false);continue;}
        if(label==L"Push Settings"){
            bool confirm=false;if(!YesNo(L"Save, rebuild, and push these settings to existing launchers",true,confirm)||!confirm||!EnsureAuthenticated(true))continue;
            std::wstring output;if(!SaveAndBuildSettings(project,edited,projects,output,error)){Notice(Red,L"!",error);Wait();continue;}
            if(PushConfig(project,error))Notice(Green,L"✓",L"Settings saved, launcher rebuilt, and settings pushed.");else Notice(Red,L"!",L"Settings were saved and the launcher was rebuilt, but pushing failed: "+error);edited=project;Wait();
        }else if(label==L"Save & Rebuild"){
            std::wstring output;if(!SaveAndBuildSettings(project,edited,projects,output,error)){Notice(Red,L"!",error);Wait();continue;}BuiltLauncherResult(L"Settings saved and launcher rebuilt at ",output);return true;
        }
    }
}
static bool OpenInExplorer(const std::wstring& path){DWORD attributes=GetFileAttributesW(path.c_str());if(attributes!=INVALID_FILE_ATTRIBUTES&&(attributes&FILE_ATTRIBUTE_DIRECTORY))return (INT_PTR)ShellExecuteW(nullptr,L"open",path.c_str(),nullptr,nullptr,SW_SHOWNORMAL)>32;std::wstring parameters=L"/select,"+Quote(path);return (INT_PTR)ShellExecuteW(nullptr,L"open",L"explorer.exe",parameters.c_str(),nullptr,SW_SHOWNORMAL)>32;}
static void OpenProjectSource(const Project& project){std::wstring url;if(project.repo.empty()){url=project.appId.substr(4);size_t tag=url.find(L'#');if(tag!=std::wstring::npos)url.resize(tag);}else{url=L"https://github.com/"+project.repo;if(!project.appKey.empty())url+=L"/releases/tag/"+project.appKey;}ShellExecuteW(nullptr,L"open",url.c_str(),nullptr,nullptr,SW_SHOWNORMAL);}
