static void ShowPublishPreview(const Project& project,const PublishPlan& plan){
    Header(project.name,L"· Publish v"+plan.version);
    Field(L"Repository",project.repo);
    Field(L"Release tag",plan.tag);
    Field(L"Release page",L"https://github.com/"+project.repo+L"/releases/tag/"+plan.tag);

    Out(L"\n");
    Field(L"Release",plan.payloadAsset+L" ← "+plan.release);
    for(const auto& release:plan.extraReleases)Field(L"Extra release",FileName(release)+L" ← "+release);
    if(project.encryption==PayloadEncryption::None)Field(L"Launcher",plan.launcherAsset);
    Field(L"Manifest",L"1KB.ini");

    Style(Bold,L"\n  Publish plan\n");
    auto step=[](const std::wstring& text){Style(Green,L"    • ");Out(text+L"\n");};
    if(plan.overwritePublished)Style(Accent,L"\n  !  This version already exists on GitHub and its files will be overwritten\n");
    if(plan.createRepository)step(L"Create and initialize the public repository");
    step(plan.replaceDraft?L"Replace unfinished release "+plan.tag:(plan.createRelease?L"Create release "+plan.tag:L"Update existing release "+plan.tag));
    if(project.encryption==PayloadEncryption::Launcher){step(L"Package the application payload");step(L"Encrypt the application payload with the existing private launcher");}
    else{step(L"Rebuild and upload the public launcher");step(L"Package the application payload");}
    if(!plan.extraReleases.empty())step(L"Upload "+std::to_wstring(plan.extraReleases.size())+L" extra release"+(plan.extraReleases.size()==1?L"":L"s"));
    step(L"Upload and verify all files, then publish the release");

    if(project.encryption==PayloadEncryption::Launcher)Style(Accent,L"\n  !  The launcher remains private and is never uploaded\n");
    Style(Green,L"\n  ✓  Ready to publish");Style(Muted,L" · No changes made yet\n\n");
}
static void ForgetProject(const Project& project){DeleteTree(project.directory);}
